import {createCommerceAction} from '@neobrutal/commerce/actions';
const root=document.querySelector('[data-commerce-component="download-entitlement"]');
root.querySelector('[data-download]').addEventListener('click',async()=>{
  const signed=await actions.dispatch(createCommerceAction('download.create',{entitlementId:root.dataset.entitlementId,releaseId:root.dataset.releaseId}));
  if(!signed?.url)throw new Error('SignedDownloadView requires a URL result');
  window.location.assign(signed.url);
});

const root=document.querySelector('[data-commerce-component="purchase-history-row"]');
function renderPurchaseHistory(order){
  if(!order?.id)throw new Error('purchase-history-row requires normalized OrderView data');
  root.dataset.orderId=order.id;
}

const root=document.querySelector('[data-commerce-component="license-card"]');
function renderLicenseCard({license,entitlement}){
  if(!license?.id||!entitlement?.id)throw new Error('license-card requires normalized license and entitlement records');
  root.dataset.licenseId=license.id;
  root.dataset.entitlementId=entitlement.id;
}

import {createCommerceAction} from '@neobrutal/commerce/actions';
const root=document.querySelector('[data-commerce-component="invoice-history"]');
async function loadInvoices(){
  const result=await actions.dispatch(createCommerceAction('invoice.list',{orderId:root.dataset.orderId}));
  const list=root.querySelector('[data-invoice-list]');
  list.replaceChildren(...result.items.map(invoice=>{const row=document.createElement('article');row.className='nbc-history-row';row.innerHTML=`<div class="nbc-history-meta"><strong></strong><small></small></div><strong></strong>`;row.querySelector('.nbc-history-meta strong').textContent=invoice.number;row.querySelector('.nbc-history-meta small').textContent=invoice.status;row.lastElementChild.textContent=invoice.total?.formatted||'';return row;}));
}
loadInvoices();

import {createCommerceAction} from '@neobrutal/commerce/actions';
const root=document.querySelector('[data-commerce-component="activation-row"]');
async function loadActivations(){
  const result=await actions.dispatch(createCommerceAction('license.activations.list',{licenseId:root.dataset.licenseId}));
  root.querySelector('[data-activation-list]').replaceChildren(...result.items.map(activation=>{const row=document.createElement('div');row.className='nbc-site-row';const code=document.createElement('code');code.textContent=activation.site||activation.domain||activation.id;row.append(code);return row;}));
}
loadActivations();

import {createCommerceAction} from '@neobrutal/commerce/actions';
const root=document.querySelector('[data-commerce-component="seat-assignment"]');
const list=root.querySelector('[data-seat-list]');
const render=items=>list.replaceChildren(...items.map(seat=>{const row=document.createElement('div');row.className='nbc-seat-row';row.dataset.seatId=seat.id;const label=document.createElement('span');label.textContent=seat.assignee?.email||seat.id;const remove=document.createElement('button');remove.type='button';remove.className='nbc-button nbc-tactile';remove.textContent='Remove';remove.addEventListener('click',async()=>render((await actions.dispatch(createCommerceAction('seat.remove',{licenseId:root.dataset.licenseId,seatId:seat.id}))).items));row.append(label,remove);return row;}));
render((await actions.dispatch(createCommerceAction('license.seats.list',{licenseId:root.dataset.licenseId}))).items);
root.querySelector('[data-seat-form]').addEventListener('submit',async event=>{event.preventDefault();const email=new FormData(event.currentTarget).get('email').toString();const result=await actions.dispatch(createCommerceAction('seat.assign',{licenseId:root.dataset.licenseId,assignee:{email},role:'member'}));render(result.items);});

import {createCommerceAction} from '@neobrutal/commerce/actions';
const root=document.querySelector('[data-commerce-component="ownership-timeline"]');
async function loadOwnershipHistory(){
  const result=await actions.dispatch(createCommerceAction('license.history.list',{licenseId:root.dataset.licenseId}));
  root.querySelector('[data-ownership-events]').replaceChildren(...result.items.map(event=>{const item=document.createElement('li');const strong=document.createElement('strong');strong.textContent=event.summary;const meta=document.createElement('small');meta.textContent=event.occurredAt;item.append(strong,meta);return item;}));
}
loadOwnershipHistory();
